import type { Component } from "vue";
import type { SettingsGroup } from "../../../../types/settings/Groups";
import { FoundryVueApplication } from "../../../foundry/apps/FoundryVueApplication";
import { notifyError } from "../../../foundry/notifications/notify-user";
import {
  groupedControls,
  requireSettingsGM,
  saveGroupedControls,
} from "../../../foundry/settings/groups/controls";
import { groupedActions, SETTINGS_GROUPS } from "../../../foundry/settings/groups/registry";
import { groupedSettingsLayout } from "../../../functions/settings/groups/layout";
import SettingsGroupApp from "./SettingsGroupApp.vue";

/** One GM-only window per settings group, each registered as its own Foundry settings menu. */
export function createSettingsGroupApplication(group: SettingsGroup) {
  const info = SETTINGS_GROUPS[group];
  return class extends FoundryVueApplication {
    static override DEFAULT_OPTIONS = {
      id: `wfrp-settings-${group}`,
      window: { title: `Compatibility Box — ${info.title}`, icon: info.icon, resizable: true },
      position: { width: 740, height: 650 },
    };
    #reloadRequired = false;

    protected override getVueComponent(): Component {
      return SettingsGroupApp;
    }

    protected override getVueProps(): Record<string, unknown> {
      requireSettingsGM();
      const controls = groupedControls(group);
      const actions = groupedActions(group);
      return {
        hint: info.hint,
        layout: groupedSettingsLayout(controls, actions),
        reloadRequired: this.#reloadRequired,
        save: async (values: Record<string, boolean | string>) => {
          try {
            this.#reloadRequired =
              (await saveGroupedControls(group, controls, values)) || this.#reloadRequired;
            ui?.notifications?.info(
              this.#reloadRequired
                ? "Settings saved. Reload connected clients to activate feature changes."
                : "Compatibility Box settings saved.",
            );
          } catch (error) {
            notifyError(error instanceof Error ? error.message : String(error), error);
          }
          // Re-read after any save or partial failure; never replay an old form snapshot.
          await this.render(true);
        },
        runAction: async (key: string) => {
          try {
            requireSettingsGM();
            const action = actions.find(([actionKey]) => actionKey === key)?.[1];
            if (action) await new action.type().render(true);
          } catch (error) {
            notifyError(error instanceof Error ? error.message : String(error), error);
          }
        },
        reload: async () => {
          requireSettingsGM();
          await foundry.applications.settings.SettingsConfig.reloadConfirm({ world: true });
        },
      };
    }
  };
}
