import type { SettingsGroup } from "../../../../types/settings/Groups";
import { MODULE_ID } from "../../../constants";
import { createSettingsGroupApplication } from "../../../apps/settings-groups/view/SettingsGroupApplication";
import { SETTINGS_GROUPS } from "./registry";

export function registerGroupedSettings(): void {
  Hooks.once("setup", () => {
    for (const group of Object.keys(SETTINGS_GROUPS) as SettingsGroup[]) {
      const info = SETTINGS_GROUPS[group];
      game?.settings.registerMenu(MODULE_ID, `settings-${group}`, {
        name: info.title,
        label: `Configure ${info.title}`,
        hint: info.hint,
        icon: info.icon,
        restricted: true,
        type: createSettingsGroupApplication(group),
      });
    }
  });
}
