<script setup lang="ts">
import type { GroupedControl } from "../../../../types/settings/Groups";

const props = defineProps<{ control: GroupedControl }>();
const model = defineModel<boolean | string>({ required: true });
const id = `wfrp-group-${props.control.key}`;
</script>

<template>
  <div class="tw:flex tw:flex-col tw:gap-1">
    <label v-if="control.type === Boolean" :for="id" class="tw:flex tw:items-center tw:gap-2">
      <input :id="id" v-model="model" type="checkbox" class="tw:dui-checkbox tw:dui-checkbox-sm" />
      <span class="tw:font-semibold">{{ control.name }}</span>
    </label>
    <template v-else>
      <label :for="id" class="tw:font-semibold">{{ control.name }}</label>
      <select
        v-if="control.choices"
        :id="id"
        v-model="model"
        class="tw:dui-select tw:dui-select-sm tw:w-full tw:min-w-0"
      >
        <option v-for="(label, value) in control.choices" :key="value" :value="value">
          {{ label }}
        </option>
      </select>
      <input
        v-else
        :id="id"
        v-model="model"
        type="text"
        class="tw:dui-input tw:dui-input-sm tw:w-full tw:min-w-0"
      />
    </template>
    <p class="tw:text-sm tw:opacity-80">
      {{ control.hint
      }}{{ control.requiresReload && !/reload/i.test(control.hint) ? " Requires a reload." : "" }}
    </p>
  </div>
</template>
