import { registerPaperDollHooks } from "./hooks";
import { isOptionalFeatureEnabled } from "../../settings/is-optional-feature-enabled";
import { isModuleActive } from "../is-module-active";

export const PAPER_DOLL_MODULE_ID = "fvtt-paper-doll-ui";
/** Body class that scopes the WFRP Paper Doll layout overrides in package.css to this integration. */
export const PAPER_DOLL_ENABLED_CLASS = "wfrp4e-compatibility-box-paper-doll";

export function registerPaperDollIntegration(): void {
  if (!isModuleActive(PAPER_DOLL_MODULE_ID)) {
    return;
  }

  if (!isOptionalFeatureEnabled("paperDoll")) {
    return;
  }

  // The switch requires a reload, so the class is set once and never needs removing.
  document.body.classList.add(PAPER_DOLL_ENABLED_CLASS);
  registerPaperDollHooks();
}
