import type {
  GroupedAction,
  GroupedControl,
  GroupedSettingsLayout,
} from "../../../../types/settings/Groups";

/** Place each control either on its own or under the action whose setting it is. */
export function groupedSettingsLayout(
  controls: GroupedControl[],
  actions: [string, GroupedAction][],
): GroupedSettingsLayout {
  const attached = new Set(actions.map(([, action]) => action.settingKey));
  return {
    controls: controls.filter((control) => !attached.has(control.key)),
    actions: actions.map(([key, { name, label, hint, icon, settingKey }]) => ({
      key,
      name,
      label,
      hint,
      icon,
      controls: controls.filter((control) => control.key === settingKey),
    })),
  };
}

/** The form's values keyed by setting, starting from the saved values. */
export function groupedSettingsValues(
  layout: GroupedSettingsLayout,
): Record<string, boolean | string> {
  return Object.fromEntries(
    [...layout.controls, ...layout.actions.flatMap((action) => action.controls)].map((control) => [
      control.key,
      control.value,
    ]),
  );
}
