<script setup lang="ts">
import { reactive, ref } from "vue";
import type { GroupedSettingsLayout } from "../../../../types/settings/Groups";
import { groupedSettingsValues } from "../../../functions/settings/groups/layout";
import SettingControl from "./SettingControl.vue";

const props = defineProps<{
  hint: string;
  layout: GroupedSettingsLayout;
  reloadRequired: boolean;
  save: (values: Record<string, boolean | string>) => Promise<void>;
  runAction: (key: string) => Promise<void>;
  reload: () => Promise<void>;
}>();

const values = reactive(groupedSettingsValues(props.layout));
const hasControls =
  props.layout.controls.length > 0 || props.layout.actions.some((a) => a.controls.length > 0);
const unsaved = ref(false);
const busy = ref(false);

async function submit(): Promise<void> {
  busy.value = true;
  // The shell re-renders after saving, so this form is replaced rather than re-enabled.
  await props.save({ ...values });
}
async function run(key: string): Promise<void> {
  busy.value = true;
  try {
    await props.runAction(key);
  } finally {
    busy.value = false;
  }
}
</script>

<template>
  <form
    class="tw:flex tw:h-full tw:min-h-0 tw:flex-col tw:gap-3"
    @submit.prevent
    @change="unsaved = true"
    @input="unsaved = true"
  >
    <p>{{ hint }}</p>
    <section class="tw:flex tw:min-h-0 tw:flex-1 tw:flex-col tw:gap-4 tw:overflow-auto">
      <SettingControl
        v-for="control in layout.controls"
        :key="control.key"
        v-model="values[control.key]!"
        :control="control"
      />
      <fieldset
        v-for="action in layout.actions"
        :key="action.key"
        class="tw:dui-fieldset tw:flex tw:flex-col tw:gap-2"
      >
        <legend class="tw:dui-fieldset-legend">{{ action.name }}</legend>
        <p class="tw:text-sm tw:opacity-80">{{ action.hint }}</p>
        <button
          type="button"
          class="tw:dui-btn tw:dui-btn-sm tw:self-start"
          :disabled="busy || unsaved"
          @click="run(action.key)"
        >
          <i :class="action.icon" aria-hidden="true" />
          {{ action.label }}
        </button>
        <SettingControl
          v-for="control in action.controls"
          :key="control.key"
          v-model="values[control.key]!"
          :control="control"
        />
      </fieldset>
      <p v-if="!hasControls && !layout.actions.length">
        No supported modules are currently available for this group.
      </p>
    </section>
    <p role="status">
      {{
        unsaved
          ? "Unsaved changes. Save before running a setup action, or close to discard."
          : reloadRequired
            ? "Saved. Reload connected clients to activate feature changes."
            : "Changes take effect when you save. Setup actions open their own review."
      }}
    </p>
    <div class="tw:flex tw:gap-2">
      <!-- A click handler, not native submit: Foundry's window handles button clicks itself. -->
      <button
        v-if="hasControls"
        type="button"
        class="tw:dui-btn tw:dui-btn-primary tw:flex-1"
        :disabled="busy"
        @click="submit"
      >
        Save Settings
      </button>
      <button
        v-if="reloadRequired"
        type="button"
        class="tw:dui-btn tw:flex-1"
        :disabled="busy"
        @click="reload"
      >
        Reload Foundry
      </button>
    </div>
  </form>
</template>
