import { MODULE_ID } from "../../../constants";
import { HEALTH_ESTIMATE_PRESET_EXTENSION } from "./preset";

interface HealthToken {
  actor?: { type: string; statuses: ReadonlySet<string> };
}
interface HealthEstimateRuntime {
  isDead: (token: HealthToken, stage: number) => boolean;
}
const patched = new WeakSet<HealthEstimateRuntime>();

let reported = false;

/**
 * Health Estimate 36.1: do not infer WFRP death from Wounds, defeated markers or module flags.
 * The canvasInit attempt may run before Health Estimate creates its API; a missing API at ready is
 * reported, since the compatibility switch would otherwise claim behavior that is not installed.
 */
export function registerHealthEstimateIntegration(phase: "canvasInit" | "ready"): void {
  if (!HEALTH_ESTIMATE_PRESET_EXTENSION.enabled?.()) return;
  const runtime =
    game && (Reflect.get(game, "healthEstimate") as HealthEstimateRuntime | undefined);
  if (!runtime || typeof runtime.isDead !== "function") {
    if (phase === "ready" && !reported) {
      reported = true;
      const message =
        "Compatibility Box: Health Estimate's death check (game.healthEstimate.isDead) is unavailable, so WFRP death detection was not installed. Health Estimate is using its own death detection.";
      console.error(`${MODULE_ID} | ${message}`);
      if (game?.user?.isGM) ui?.notifications?.error(message, { permanent: true });
    }
    return;
  }
  if (patched.has(runtime)) return;
  const original = runtime.isDead;
  runtime.isDead = function (token, stage) {
    if (token.actor && ["character", "npc", "creature"].includes(token.actor.type)) {
      return token.actor.statuses.has("dead");
    }
    return original.call(this, token, stage);
  };
  patched.add(runtime);
}
