import { createPinia } from "pinia";
import { type App, type Component, createApp } from "vue";

// Shared by ordinary applications and Foundry's document-sheet subclasses.
export class VueMount {
  #app: App<Element> | undefined;

  createRoot(): HTMLElement {
    const root = document.createElement("div");
    root.classList.add("wfrp4e-compatibility-box-root");
    root.dataset["theme"] = "wfrp4e-compatibility-box";
    return root;
  }

  mount(
    root: HTMLElement,
    content: HTMLElement,
    component: Component,
    props: Record<string, unknown>,
  ): void {
    this.unmount();
    content.classList.add("wfrp4e-compatibility-box-app");
    content.replaceChildren(root);
    this.#app = createApp(component, props);
    this.#app.use(createPinia());
    this.#app.mount(root);
  }

  unmount(): void {
    this.#app?.unmount();
    this.#app = undefined;
  }
}
